import yaml
from pathlib import Path

def validate_skill_md(path):
    """Validate SKILL.md frontmatter and structure."""
    skill_md = (path / "SKILL.md").read_text(encoding="utf-8")

    if not skill_md.startswith("---"):
        return False, "No frontmatter found"

    # Extract frontmatter
    match_end = skill_md[3:].find("---")
    if match_end == -1:
        return False, "Unclosed frontmatter"

    fm_text = skill_md[3:match_end+3]
    try:
        fm = yaml.safe_load(fm_text) or {}
    except yaml.YAMLError as e:
        return False, f"Invalid YAML: {e}"

    # Required fields
    required = ['name', 'triggers', 'description']
    missing = [f for f in required if f not in fm]
    if missing:
        return False, f"Missing fields: {missing}"

    # Check content after frontmatter
    content_start = match_end + 6
    if content_start >= len(skill_md):
        return False, "No content after frontmatter"

    content = skill_md[content_start:].strip()
    if not content.startswith("#"):
        return False, "Content should start with markdown heading"

    return True, {
        'name': fm.get('name'),
        'triggers': len(fm.get('triggers', [])),
        'has_description': bool(fm.get('description')),
        'user_invocable': fm.get('user-invocable', True),
        'lines': len(skill_md.splitlines()),
    }

